function readStored<T>(key:string, fallback:T):T { try { const raw=localStorage.getItem(key);if(!raw)return fallback;const value=JSON.parse(raw);if(Array.isArray(fallback))return (Array.isArray(value)?value:fallback) as T;return typeof fallback==='object'&&fallback!==null&&typeof value==='object'&&value!==null&&!Array.isArray(value)?{...fallback,...value}:fallback } catch { return fallback } }
function readLocal(key:string,fallback='') { try{return localStorage.getItem(key)??fallback}catch{return fallback} }
function readRawLocal(key:string):string|null { try{return localStorage.getItem(key)}catch{return null} }
function writeLocal(key:string,value:string) { try{localStorage.setItem(key,value)}catch{/* Keep the workspace usable when browser storage is disabled or full. */} }
function utc(value:string) { return formatUtcTime(value,'en-GB') }
function local(value:string, zone?:string) { return formatLocalTime(value,zone) }
function amount(mm:number|null, settings:Settings, digits=1) {
  return formatAmount(mm,settings.units,digits)
}
function timeLabels(value:string,settings:Settings,locationZone?:string|null) {
  return forecastTimeLabels(value,settings.timezone,locationZone)
}
function intervalTimes(series:Series,value:Point):[string,string] {
  const start=new Date(Date.parse(series.run_time_utc)+value.display_interval_hours[0]*3600000).toISOString()
  const end=new Date(Date.parse(series.run_time_utc)+value.display_interval_hours[1]*3600000).toISOString()
  return [start,end]
}
function formatTime(value:string, settings:Settings, locationZone?:string|null) {
  const labels=forecastTimeLabels(value,settings.timezone,locationZone)
  if(settings.timezone==='UTC')return labels.primary
  if(settings.timezone==='device')return `${labels.primary} (${labels.secondary})`
  return locationZone&&isValidIanaTimeZone(locationZone)?`${labels.primary} (${labels.secondary})`:`${labels.primary} · selected-place time zone unavailable`
}
function intervalLabel(series:Series,value:Point,settings:Settings,locationZone?:string|null) { const start=new Date(Date.parse(series.run_time_utc)+value.display_interval_hours[0]*3600000).toISOString(),end=new Date(Date.parse(series.run_time_utc)+value.display_interval_hours[1]*3600000).toISOString();return `${formatTime(start,settings,locationZone)} – ${formatTime(end,settings,locationZone)}` }
function forecastWindowLabel(series:Series,hours:number,settings:Settings,locationZone?:string|null) { const start=series.run_time_utc,end=new Date(Date.parse(start)+hours*3600000).toISOString();return `${formatTime(start,settings,locationZone)} – ${formatTime(end,settings,locationZone)}` }
function absoluteIntervalLabel(run:string,interval:[number,number],settings:Settings,zone?:string|null) { const start=new Date(Date.parse(run)+interval[0]*3600000).toISOString(),end=new Date(Date.parse(run)+interval[1]*3600000).toISOString();return `${formatTime(start,settings,zone)} – ${formatTime(end,settings,zone)}` }
function ageLabel(value:string) { const hours=Math.max(0,Math.floor((Date.now()-Date.parse(value))/3600000)); return hours<1?'under 1 h old':hours<48?`${hours} h old`:`${Math.floor(hours/24)} d old` }
function LocationPinIcon(){return <svg className="location-pin-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true" focusable="false"><path d="M19 10c0 5.2-7 11-7 11S5 15.2 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.2"/></svg>}
